import{z as s,x as i,o as e,c as l,q as A,j as r,D as a,d as t,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"NUMA","description":"","frontmatter":{"title":"NUMA","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/par-numa.md","filePath":"cs/par-numa.md","lastUpdated":1791063341000}'),p={name:"cs/par-numa.md"};function m(c,E,d,h,u,D){const B=i("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="numa" tabindex="-1">NUMA <a class="header-anchor" href="#numa" aria-label="Permalink to &quot;NUMA&quot;">​</a></h1><div class="epigraph"><p>同一物理地址，不等于同一访问代价：内存控制器长在插槽里，跨过互连的每一次访存都在还路费。</p><footer>—— 据 Drepper, What Every Programmer Should Know About Memory, 2007；Lameter, NUMA: An Overview, ACM Queue 2013 整理</footer></div><p><a href="/cs/par-simd-vectorization">上一课</a>把单核内的并行吃满；核再多、插槽再多，下一个成本跳变不在指令里，而在「这段内存在哪」。<a href="/cs/interconnect-numa">互连与 NUMA</a>已给过体系结构账：地址全局共享，本地与远程延迟分档；<a href="/cs/numa-mempolicy">NUMA 内存策略</a>与 <a href="/cs/numa-sched">NUMA 调度</a>给过 OS 侧的旋钮。缺口在程序侧的模式：什么时候「一次访存一个价」的假设会拖垮并行程序，怎么把数据放到用它的核旁边。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NUMA 打破的是从 PRAM 一路残留下来的「访存均匀」假设：跨插槽的远程访问延迟更高、带宽更低，还要挤占互连。错法一：主线程一口气初始化大数组——物理页全部落在 0 号节点，之后其他节点的线程每次访问都过互连；扩展曲线常常在第二个插槽就断。错法二：线程在节点间漂移——缓存与内存的亲和全丢；<a href="/cs/cpu-affinity">CPU 亲和</a>在 NUMA 上不是洁癖，是正确性前提。错法三：只盯延迟不看带宽——远程带宽通常比远程延迟先成为瓶颈，因为一致性流量与别人的正常流量挤同一条互连。</p><p><span class="marginnote">数字实例：本地访存若约 80 ns，远程常要 110–140 ns，带宽还可能只剩一半甚至更少——相当于从隔壁工位拿文件变成跨城快递，而且跨城的路只有一条，大家共享。扩展曲线在第二个插槽拐弯，多半就是这笔账在起作用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法三步：分区、放置、验证。分区：把数据按「谁用谁拥有」切开，每个节点处理自己的份额——数据并行的分区思想从循环内挪到插槽之间；只读数据可以每节点复制一份，用空间换互连流量，代价是更新要传播。放置：first-touch 规则决定页落点——谁先写，页归谁的节点——所以并行初始化是常规动作：让将要用这页的线程碰第一下；线程用亲和钉在节点上，与内存策略（绑定、交错、首选）对齐。验证：本地与远程的延迟、带宽分开量——Drepper 的测量表里远程通常多付三到七成——再看强扩展曲线在几个插槽处拐弯。</p><p><span class="marginnote">first-touch 可以类比成「谁先入住，房产证写谁」：页不是按「谁用得多」分的，而是按「谁第一个写它」分的。所以初始化这一次的落点决定终身——分错了，之后每一次访问都在还路费，除非花钱搬家（页迁移）。</span></p>',9)),(e(),r(n,null,{default:a(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FT%5B%22%E4%B8%BB%E7%BA%BF%E7%A8%8B%E5%86%99%E5%AE%8C%E5%85%A8%E9%83%A8%E9%A1%B5%22%5D%20--%3E%20HOME%5B%22%E9%A1%B5%E5%85%A8%E8%90%BD%200%20%E5%8F%B7%E8%8A%82%E7%82%B9%22%5D%0A%20%20HOME%20--%3E%20REMOTE%5B%22%E5%85%B6%E4%BB%96%E8%8A%82%E7%82%B9%E6%AF%8F%E6%AC%A1%E8%AE%BF%E9%97%AE%E8%BF%87%E4%BA%92%E8%BF%9E%22%5D%0A%20%20REMOTE%20--%3E%20SLOW%5B%22%E6%89%A9%E5%B1%95%E6%9B%B2%E7%BA%BF%E6%8F%90%E5%89%8D%E6%8B%90%E5%BC%AF%22%5D%0A%20%20FIX%5B%22%E5%B9%B6%E8%A1%8C%E5%88%9D%E5%A7%8B%E5%8C%96%20%2B%20CPU%20%E4%BA%B2%E5%92%8C%20%2B%20mempolicy%22%5D%20--%3E%20LOCAL%5B%22%E9%A1%B5%E8%90%BD%E5%9C%A8%E7%94%A8%E5%AE%83%E7%9A%84%E8%8A%82%E7%82%B9%22%5D%0A%20%20LOCAL%20--%3E%20FAST%5B%22%E6%9C%AC%E5%9C%B0%E8%AE%BF%E9%97%AE%EF%BC%9A%E5%BB%B6%E8%BF%9F%E4%BD%8E%E3%80%81%E5%B8%A6%E5%AE%BD%E8%B6%B3%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制账在互连上：远程访问占用的不只是自己那一份带宽——目录查询、远端缓存的一致性回写、别的插槽的正常流量都走同一条路；<a href="/cs/false-sharing">伪共享</a>的行乒乓在 NUMA 上从跨核升级成跨插槽，代价翻几倍。自动 NUMA balancing 的机制是缺页采样：内核故意让错节的访问出缺页，把页迁向实际使用方——它治已病不治未病，搬页本身有抖动，负载一变又重来；设计期放对页，永远比运行期搬家便宜。同插槽内也并非严格均匀：mesh 拓扑下核到内存控制器的跳数不同，UMA 是近似的近似，不要在账本里当成精确事实。</p><p><span class="marginnote">first-touch 陷阱的标准修法：把主线程的初始化循环改成并行版（如 <code>#pragma omp parallel for</code>），让每个页被将要用它的节点碰到；事后 <code>migrate_pages</code> 也能搬，但那是补救，不是设计。</span></p><p>方法一节的图画的是「错法与修法的前后对照」；一次远程访存在路上具体要经过什么、为什么带宽先崩，值得单独画出来。</p>',4)),(e(),r(n,null,{default:a(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%8A%82%E7%82%B9%201%20%E7%9A%84%E6%A0%B8%E8%A6%81%E8%AF%BB%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20Q%7B%22%E9%A1%B5%E8%90%BD%E5%9C%A8%E5%93%AA%E4%B8%AA%E8%8A%82%E7%82%B9%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9C%AC%E8%8A%82%E7%82%B9%22%7C%20L%5B%22%E6%9C%AC%E5%9C%B0%E5%86%85%E5%AD%98%20%E5%BB%B6%E8%BF%9F%E4%BD%8E%E5%B8%A6%E5%AE%BD%E8%B6%B3%22%5D%0A%20%20Q%20--%3E%7C%22%E8%8A%82%E7%82%B9%200%22%7C%20I%5B%22%E8%B7%A8%E6%8F%92%E6%A7%BD%E4%BA%92%E8%BF%9E%22%5D%0A%20%20I%20--%3E%20D%5B%22%E7%9B%AE%E5%BD%95%E6%9F%A5%E8%AF%A2%E4%B8%8E%E4%B8%80%E8%87%B4%E6%80%A7%E5%9B%9E%E5%86%99%22%5D%0A%20%20I%20--%3E%20M%5B%22%E8%8A%82%E7%82%B9%200%20%E7%9A%84%E5%86%85%E5%AD%98%22%5D%0A%20%20D%20--%3E%20J%5B%22%E4%B8%8E%E5%88%AB%E4%BA%BA%E7%9A%84%E6%AD%A3%E5%B8%B8%E6%B5%81%E9%87%8F%E6%8C%A4%E5%90%8C%E4%B8%80%E6%9D%A1%E8%B7%AF%22%5D%0A%20%20J%20--%3E%20B%5B%22%E8%BF%9C%E7%A8%8B%E5%B8%A6%E5%AE%BD%E5%85%88%E4%BA%8E%E5%BB%B6%E8%BF%9F%E6%88%90%E4%B8%BA%E7%93%B6%E9%A2%88%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>目录一致性协议已在<a href="/cs/interconnect-numa">互连与 NUMA</a> 给过，不重讲；CXL 与分层内存、GPU 的 HBM 分区不写。内存策略 API 的逐一罗列归 numa-mempolicy，本课只取模式。远程访问的常数也因平台而异：比值随代际与拓扑变，账要自己量，不要引用别家机器的数字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NUMA 打掉「一次访存一个价」：本地与远程的延迟、带宽分档。</li><li>分区、放置、验证：数据按使用方切，first-touch 落页，亲和钉线程。</li><li>远程带宽常先于延迟成为瓶颈；伪共享跨插槽代价翻倍。</li><li>自动 balancing 治已病；设计期的并行初始化才是正解。</li><li>出处：Drepper, What Every Programmer Should Know About Memory, 2007；Lameter, ACM Queue 2013。</li></ul><p><span class="marginnote">术语翻译「目录」（directory）：它是内存控制器旁的一本记账本，记着每条缓存行被哪些插槽的核缓存过；谁要写，它就负责挨个通知作废。远程访存的额外开销里，很大一块就是这本账簿的查询与广播——不是简单的「线长了所以慢」。</span></p>',5))])}const f=s(p,[["render",m]]);export{C as __pageData,f as default};
